import * as React from 'react'
import { cn } from '@/lib/utils'
import { useMergedRefs } from '@/lib/merge-refs'
import { useDragReorder } from '@/hooks/use-drag-reorder'
import { useReducedMotion } from '@/hooks/use-reduced-motion'
import { useScrollFade } from '@/hooks/use-scroll-fade'

// Ref map keyed by item index; rebuilt each render but stable enough for
// scroll-into-view after arrow moves.
type ItemRefMap = Map<number, HTMLLIElement>

// Inline SVG arrows -- same documented exception as the Select caret so the
// DS stays free of icon library dependencies.
function ArrowUpIcon() {
  return (
    <svg
      viewBox="0 0 14 14"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
      className="w-3.5 h-3.5"
    >
      <path d="M7 11V3M3.5 6.5L7 3l3.5 3.5" />
    </svg>
  )
}

function ArrowDownIcon() {
  return (
    <svg
      viewBox="0 0 14 14"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
      className="w-3.5 h-3.5"
    >
      <path d="M7 3v8M3.5 7.5L7 11l3.5-3.5" />
    </svg>
  )
}

// Inline drag handle SVG -- avoids requiring DotsSixVertical from Phosphor.
function DragHandleIcon() {
  return (
    <svg
      viewBox="0 0 18 18"
      fill="currentColor"
      aria-hidden
      className="w-[18px] h-[18px] shrink-0 text-[var(--color-text-muted-light)] dark:text-[var(--color-text-muted-dark)]"
    >
      <circle cx="6" cy="4" r="1.5" />
      <circle cx="12" cy="4" r="1.5" />
      <circle cx="6" cy="9" r="1.5" />
      <circle cx="12" cy="9" r="1.5" />
      <circle cx="6" cy="14" r="1.5" />
      <circle cx="12" cy="14" r="1.5" />
    </svg>
  )
}

/**
 * The scroller a touch drag should auto-scroll: the list itself when the caller
 * height-capped it, else its nearest scrollable ancestor (a drawer body, a
 * page's <main>). Walking up matters because the same list is height-capped in
 * one app and flows into the page scroller in another.
 */
function findScrollParent(el: HTMLElement | null): HTMLElement | null {
  let node: HTMLElement | null = el
  while (node) {
    const overflowY = getComputedStyle(node).overflowY
    if (
      (overflowY === 'auto' || overflowY === 'scroll') &&
      node.scrollHeight > node.clientHeight
    ) {
      return node
    }
    node = node.parentElement
  }
  return null
}

export interface ReorderListProps<T> {
  /** The ordered array of items to display. */
  items: T[]
  /** Returns a stable string key for each item. */
  getId: (item: T) => string
  /** Renders the item label/content inside the row. */
  renderLabel: (item: T) => React.ReactNode
  /** Called with the new array whenever the user commits a reorder. */
  onReorder: (next: T[]) => void
  /** aria-label for the move-up button. Pass a translated string. */
  moveUpLabel?: string
  /** aria-label for the move-down button. Pass a translated string. */
  moveDownLabel?: string
  className?: string
  /** Inline styles for the root element. */
  style?: React.CSSProperties
}

/**
 * Accessible drag-and-drop + arrow-button reorder list.
 *
 * Built on the existing DS `useDragReorder` hook. Includes ArrowUp / ArrowDown
 * keyboard/touch-friendly buttons (accessibility improvement from Uradi's
 * `ListOrderReorder`). Arrow icons use inline SVG so the DS stays icon-free.
 *
 * Props:
 * - `items` / `getId` / `renderLabel` / `onReorder` -- the data contract
 * - `moveUpLabel` / `moveDownLabel` -- translated aria-labels for the buttons
 *
 * The caller owns the state; `onReorder` receives the new array and should
 * update state + persist as needed.
 *
 * Long lists: pass `className="max-h-72 overflow-y-auto"` (or similar) to cap
 * the height and enable internal scrolling. Native HTML5 drag auto-scrolls
 * scrollable ancestors in modern browsers; arrow button moves scroll the moved
 * item into view automatically. Add `pr-1` to give the scrollbar a little
 * breathing room so it does not overlap row content.
 *
 * **Touch**: the drag handle carries the pointer path (`getHandleProps`), so a
 * finger on the handle drags and a finger anywhere else on the row still
 * scrolls. That split is deliberate -- the row stays scrollable so a capped
 * list inside a drawer is not a gesture trap. Auto-scroll targets the list
 * itself when height-capped, otherwise the nearest scrollable ancestor.
 */
function ReorderListInner<T>(
  {
    items,
    getId,
    renderLabel,
    onReorder,
    moveUpLabel = 'Move up',
    moveDownLabel = 'Move down',
    className,
    style,
  }: ReorderListProps<T>,
  ref: React.ForwardedRef<HTMLUListElement>,
) {
  // Holds a ref to each rendered <li> by its current index. Used to scroll the
  // moved item into view after an arrow-button move.
  const itemRefs = React.useRef<ItemRefMap>(new Map())

  // Edge-fade masks for the height-capped scrolling case (the caller passes a
  // max-h + overflow className): the overflowing edge fades out, both edges
  // once scrolled. Resolves to no class while the list has no overflow.
  const listRef = React.useRef<HTMLUListElement>(null)
  const mergedRef = useMergedRefs(listRef, ref)
  const fade = useScrollFade(listRef, items.length)

  const reduced = useReducedMotion()

  const reorder = useDragReorder(
    (from, to) => {
      const next = [...items]
      const [moved] = next.splice(from, 1)
      next.splice(to, 0, moved)
      onReorder(next)
    },
    {
      count: items.length,
      getItemElement: (index) => itemRefs.current.get(index) ?? null,
      // Resolved per call rather than cached: whether the list is its own
      // scroller depends on the caller's className, and an expandable list
      // (Chip Away's goal order) changes that answer at runtime.
      getScrollContainer: () => findScrollParent(listRef.current),
    },
  )

  const moveBy = (index: number, delta: number) => {
    const newIndex = index + delta
    if (newIndex < 0 || newIndex >= items.length) return
    const next = [...items]
    const [moved] = next.splice(index, 1)
    next.splice(newIndex, 0, moved)
    onReorder(next)
    // After the parent re-renders with the new order, scroll the moved item --
    // now at newIndex -- into view. requestAnimationFrame waits for the DOM
    // update so the ref map reflects the new positions.
    requestAnimationFrame(() => {
      itemRefs.current.get(newIndex)?.scrollIntoView({
        block: 'nearest',
        behavior: reduced ? 'auto' : 'smooth',
      })
    })
  }

  return (
    <ul ref={mergedRef} className={cn('space-y-1.5 overscroll-contain', fade, className)} style={style}>
      {items.map((item, index) => {
        const id = getId(item)
        const isDragging = reorder.draggingIndex === index
        const isOver =
          reorder.dragOverIndex === index && reorder.draggingIndex !== index

        return (
          <li
            key={id}
            ref={(el) => {
              if (el) {
                itemRefs.current.set(index, el)
              } else {
                itemRefs.current.delete(index)
              }
            }}
            {...reorder.getItemProps(index)}
            className={cn(
              // py + the 28px nudge buttons + the border stay UNDER the 44px floor, so
              // min-h is what sets the row height and it matches every other
              // control. Taller buttons here push the row past it instead.
              'flex items-center gap-2 min-h-control-md px-3 py-1.5 rounded-lg border transition-colors',
              'cursor-grab active:cursor-grabbing select-none',
              // A pointer drag repaints rows under a still finger, so the
              // color transition would lag the reorder it is describing.
              reorder.pointerDragging && 'transition-none',
              'bg-[var(--color-surface-light)] border-[var(--color-border-light)] text-[var(--color-text-primary-light)]',
              'dark:bg-[var(--color-surface-dark)] dark:border-[var(--color-border-dark)] dark:text-[var(--color-text-primary-dark)]',
              isDragging && 'opacity-50',
              isOver && 'border-[var(--color-accent-500)]',
            )}
          >
            {/* The touch grip. Padded out to a real target rather than sized to
                the glyph, and `touch-action: none` (from getHandleProps) makes
                a drag starting here a drag rather than a scroll. */}
            <span
              {...reorder.getHandleProps(index)}
              aria-hidden
              className="-my-1.5 py-1.5 -ms-1 ps-1 pe-1 shrink-0 cursor-grab active:cursor-grabbing"
            >
              <DragHandleIcon />
            </span>
            <span className="flex-1 truncate text-sm font-medium">
              {renderLabel(item)}
            </span>
            <div className="flex gap-1 shrink-0">
              <button
                type="button"
                aria-label={moveUpLabel}
                title={moveUpLabel}
                disabled={index === 0}
                onClick={() => moveBy(index, -1)}
                className={cn(
                  'wj-focus-ring h-7 w-7 inline-flex items-center justify-center rounded text-xs font-bold',
                  'border border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]',
                  'text-[var(--color-text-secondary-light)] dark:text-[var(--color-text-secondary-dark)]',
                  'hover:bg-[var(--color-surface-muted-light)] dark:hover:bg-[var(--color-surface-muted-dark)]',
                  'disabled:opacity-40 disabled:cursor-not-allowed',
                )}
              >
                <ArrowUpIcon />
              </button>
              <button
                type="button"
                aria-label={moveDownLabel}
                title={moveDownLabel}
                disabled={index === items.length - 1}
                onClick={() => moveBy(index, 1)}
                className={cn(
                  'wj-focus-ring h-7 w-7 inline-flex items-center justify-center rounded text-xs font-bold',
                  'border border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]',
                  'text-[var(--color-text-secondary-light)] dark:text-[var(--color-text-secondary-dark)]',
                  'hover:bg-[var(--color-surface-muted-light)] dark:hover:bg-[var(--color-surface-muted-dark)]',
                  'disabled:opacity-40 disabled:cursor-not-allowed',
                )}
              >
                <ArrowDownIcon />
              </button>
            </div>
          </li>
        )
      })}
    </ul>
  )
}

// forwardRef erases the generic type parameter, so re-assert it on the exported
// component: ReorderList keeps `items`/`getId`/`renderLabel`/`onReorder` typed
// to T AND forwards a ref to the <ul> element.
const ReorderListWithRef = React.forwardRef(ReorderListInner)
ReorderListWithRef.displayName = 'ReorderList'
export const ReorderList = ReorderListWithRef as <T>(
  props: ReorderListProps<T> & { ref?: React.Ref<HTMLUListElement> },
) => React.ReactElement
